import{_ as e,c as t,o,a as r}from"./app.19f3f8f0.js";const y=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"privacy-policy/index.md"}'),i={name:"privacy-policy/index.md"},a=r('<p><strong>Privacy Policy</strong></p><p>Effective Date: 2023-02-27<br> Last Updated: 2025-04-19</p><p>TLDR built the tl-dr app as an Ad-Supported app. This Service is provided by TLDR at no cost and is intended for use as-is.</p><p>This Privacy Policy describes how we collect, use, and disclose your personal information when you use our Service, in accordance with the laws of the Republic of Korea and applicable international regulations such as the General Data Protection Regulation (GDPR) and the California Consumer Privacy Act (CCPA).</p><hr><p><strong>1. Information Collection and Use</strong></p><p>We may collect personal information to improve and provide our services. The types of data we collect include:</p><ul><li>Device information (IP address, OS version, device ID)</li><li>Usage information (log data, interactions, error reports)</li><li>Identifiers used for ads</li></ul><p>We do not sell personal data to third parties.</p><hr><p><strong>2. Third-Party Services</strong></p><p>The app uses the following third-party services that may collect information:</p><ul><li><a href="https://support.google.com/admob/answer/6128543?hl=en" target="_blank" rel="noreferrer">AdMob (Google)</a></li></ul><p>We recommend reviewing their privacy policies.</p><hr><p><strong>3. Log Data</strong></p><p>When you use our Service and an error occurs, we collect log data through third-party tools. This may include device IP address, OS version, app configuration, timestamp, and usage statistics.</p><hr><p><strong>4. Cookies</strong></p><p>While our app does not explicitly use cookies, third-party services integrated within the app may use them to enhance their services. You can manage cookie settings via your device.</p><hr><p><strong>5. Children&#39;s Privacy</strong></p><p>This Service is not intended for children under 13 years of age. We do not knowingly collect personal information from children. If we learn that we have collected information from a child under 13, we will delete it immediately.</p><hr><p><strong>6. Your Rights (GDPR / CCPA)</strong></p><p>If you are a resident of the EEA (European Economic Area) or California, you have the right to:</p><ul><li>Access, correct, or delete your personal data</li><li>Withdraw consent</li><li>Object to processing</li><li>Request data portability</li><li>Opt out of the sale of personal information (CCPA)</li></ul><p>To exercise your rights, contact us at <a href="mailto:main@tl-dr.in" target="_blank" rel="noreferrer">main@tl-dr.in</a>.</p><hr><p><strong>7. Data Retention and Security</strong></p><p>We retain your personal data only for as long as necessary to fulfill the purposes outlined. We use commercially reasonable security practices to protect your data, but no method of transmission is 100% secure.</p><hr><p><strong>8. International Data Transfers</strong></p><p>As we operate globally, your data may be transferred to and processed in countries other than your own, including South Korea. We ensure adequate safeguards are in place.</p><hr><p><strong>9. Legal Basis for Processing (GDPR)</strong></p><p>We process your data based on:</p><ul><li>Your consent</li><li>Contractual necessity</li><li>Legal obligation</li><li>Legitimate interest</li></ul><hr><p><strong>10. Changes to This Policy</strong></p><p>We may update this Privacy Policy. Any changes will be posted on this page with an updated effective date. Continued use of the Service after changes constitutes acceptance.</p><hr><p><strong>11. Governing Law</strong></p><p>This Privacy Policy is governed by the laws of the Republic of Korea. Any disputes arising will be subject to the exclusive jurisdiction of the courts in Seoul, Korea.</p><hr><p><strong>Contact Us</strong></p><p>If you have any questions or requests regarding this Privacy Policy, please contact:<br> 📧 <a href="mailto:main@tl-dr.in" target="_blank" rel="noreferrer">main@tl-dr.in</a></p>',47),n=[a];function s(l,c,p,d,u,h){return o(),t("div",null,n)}const f=e(i,[["render",s]]);export{y as __pageData,f as default};
